-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- artist-and-shirt
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: our artist and the 2026 shirt',
  'Meet the artist behind Signal',
  'Jenni Jean won our artist call-out. Her artwork will be with us all day.',
  'subscribers',
  $nl$[{"id":"artist-and-shirt-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/artwork-authenticity.jpg","alt":"Authenticity, an artwork by Jenni Jean: rows of red fingerprints with a single gold one","widthPct":"full"},{"id":"artist-and-shirt-02","type":"header","text":"Meet the artist behind Signal.","size":"lg"},{"id":"artist-and-shirt-03","type":"text","html":"<p>When we put out a call for artists to shape the look of Signal, the response from Newcastle's creative community was incredible.</p><p>One piece stopped us. It's called <strong>Authenticity</strong>, and it's by <strong>Jenni Jean</strong>, our winning artist.</p><p>Thank you, Jenni, for trusting us with your work. It will be with us throughout the day, and we can't wait for everyone to see it in the room.</p>"},{"id":"artist-and-shirt-04","type":"button","label":"See more of Jenni's work","href":"https://jennijeanart.com.au","align":"center","theme":"ink","variant":"outline"},{"id":"artist-and-shirt-05","type":"divider","style":"short","colour":"soft"},{"id":"artist-and-shirt-06","type":"header","text":"Wearing the artwork","size":"md"},{"id":"artist-and-shirt-07","type":"text","html":"<p>Jenni's artwork also lands on this year's Signal shirt: the event details on the front, and the full piece on the back.</p>"},{"id":"artist-and-shirt-08","type":"columns","cols":[[{"id":"artist-and-shirt-09","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/shirt-front.jpg","alt":"The front of the 2026 Signal shirt","widthPct":100},{"id":"artist-and-shirt-10","kind":"text","html":"<p>Front</p>"}],[{"id":"artist-and-shirt-11","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/shirt-back.jpg","alt":"The back of the 2026 Signal shirt, showing Jenni Jean's artwork","widthPct":100},{"id":"artist-and-shirt-12","kind":"text","html":"<p>Back</p>"}]],"ratio":"50-50","valign":"top"},{"id":"artist-and-shirt-13","type":"divider","style":"short","colour":"soft"},{"id":"artist-and-shirt-14","type":"header","text":"See it in person","size":"md"},{"id":"artist-and-shirt-15","type":"text","html":"<p>Signal is on Saturday 24 October at the Conservatorium of Music, with Jenni's artwork on show all day.</p>"},{"id":"artist-and-shirt-16","type":"button","label":"Get your ticket","href":"https://tedxnewy.com.au/signal","align":"center","theme":"red","variant":"solid"},{"id":"artist-and-shirt-17","type":"text","html":"<p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: our artist and the 2026 shirt'
);

-- partner-thank-you
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: thank you to our partners',
  'Thank you, Newy',
  'Signal only happens because of the people and businesses who back it.',
  'subscribers',
  $nl$[{"id":"partner-thank-you-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/community.jpg","alt":"Attendees at a TEDxNewy event applauding","widthPct":"full"},{"id":"partner-thank-you-02","type":"header","text":"Thank you, Newy.","size":"lg"},{"id":"partner-thank-you-03","type":"text","html":"<p>Watching this city get behind the Knights in the NRL grand final was something special. A whole community pulling in the same direction.</p><p>Our event is a dwarf in comparison, but the feeling is the same. TEDxNewy has grown every year, and that has never happened without the support of our community.</p><p>As Signal gets closer, we want to say thank you.</p>"},{"id":"partner-thank-you-04","type":"image","src":"https://tedxnewy.com.au/images/newsletter/partners-lockup.jpg","alt":"Our partners: University of Newcastle, Henderson, Hey Zomi, Frekl, Newy Digital and Sketch It Live","widthPct":100},{"id":"partner-thank-you-05","type":"text","html":"<p>To the University of Newcastle, Henderson, Hey Zomi, Frekl, Newy Digital and Sketch It Live: thank you for backing a volunteer-run event and for believing in what we're building.</p>"},{"id":"partner-thank-you-06","type":"button","label":"Meet our partners","href":"https://tedxnewy.com.au/sponsors","align":"center","theme":"ink","variant":"outline"},{"id":"partner-thank-you-07","type":"divider","style":"short","colour":"soft"},{"id":"partner-thank-you-08","type":"header","text":"What your support makes possible","size":"md"},{"id":"partner-thank-you-09","type":"text","html":"<p><strong>A drinks hour for everyone.</strong> Local partners have made it possible to end the day together, with a drink in hand and the conversations still going.</p><p><strong>Offers across event week.</strong> Cafes, restaurants, bars and hotels around Newcastle have put together exclusive offers, so the event spills out into the whole city.</p><p><strong>Schools in the room.</strong> Our school partnerships bring young Novocastrians into the conversation, and their ideas onto the walls.</p><p><strong>Angel tickets.</strong> Every Angel ticket pays for a seat for someone who might not otherwise be there. Thank you to everyone who has paid it forward.</p><p><strong>Local makers.</strong> Local vendors have helped us produce the shirts, banners and materials you'll see on the day, and we're proud to keep that work in Newcastle.</p>"},{"id":"partner-thank-you-10","type":"button","label":"See what's on during event week","href":"https://tedxnewy.com.au/downloads/make-the-most-of-event-week-guide.pdf","align":"center","theme":"red","variant":"solid"},{"id":"partner-thank-you-11","type":"divider","style":"short","colour":"soft"},{"id":"partner-thank-you-12","type":"text","html":"<p>If you've bought a ticket, shared the event with a friend, or just cheered us on, that's part of this too.</p><p>See you on Saturday 24 October.</p><p>Will and the TEDxNewy team</p>"},{"id":"partner-thank-you-13","type":"button","label":"Get your ticket","href":"https://tedxnewy.com.au/signal","align":"center","theme":"ink","variant":"solid"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: thank you to our partners'
);

-- ticket-holder-event-details
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: ticket holder event details',
  'Signal is this Saturday: everything you need to know',
  'Doors, session times, the drinks hour and what to expect on the day.',
  'ticket-purchasers',
  $nl$[{"id":"ticket-holder-event-details-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-hero.jpg","alt":"A packed audience at a TEDxNewy event","widthPct":"full"},{"id":"ticket-holder-event-details-02","type":"header","text":"See you on Saturday.","size":"lg"},{"id":"ticket-holder-event-details-03","type":"text","html":"<p>Signal is almost here, and we can't wait to share the day with you.</p><p>Here is everything you need to know before you arrive.</p>"},{"id":"ticket-holder-event-details-04","type":"header","text":"Where and when","size":"md"},{"id":"ticket-holder-event-details-05","type":"text","html":"<p><strong>Saturday 24 October 2026</strong><br>Doors open at 1:30pm<br>Conservatorium of Music, corner Laman Street and Auckland Street, Newcastle NSW 2300</p>"},{"id":"ticket-holder-event-details-06","type":"button","label":"Get directions","href":"https://www.google.com/maps/search/?api=1&query=Newcastle+Conservatorium+of+Music","align":"center","theme":"ink","variant":"outline"},{"id":"ticket-holder-event-details-07","type":"divider","style":"short","colour":"soft"},{"id":"ticket-holder-event-details-08","type":"header","text":"Your day","size":"md"},{"id":"ticket-holder-event-details-09","type":"columns","cols":[[{"id":"ticket-holder-event-details-09-t","kind":"text","html":"<p><strong>1:30pm to 2:00pm</strong></p>"}],[{"id":"ticket-holder-event-details-09-b","kind":"text","html":"<p><strong>Arrival and registration</strong><br>Doors open. Check in, grab your name badge and find your seat.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"ticket-holder-event-details-10","type":"columns","cols":[[{"id":"ticket-holder-event-details-10-t","kind":"text","html":"<p><strong>2:00pm to 3:30pm</strong></p>"}],[{"id":"ticket-holder-event-details-10-b","kind":"text","html":"<p><strong>Session 1</strong><br>We open the event, followed by talks and performances.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"ticket-holder-event-details-11","type":"columns","cols":[[{"id":"ticket-holder-event-details-11-t","kind":"text","html":"<p><strong>3:30pm to 4:00pm</strong></p>"}],[{"id":"ticket-holder-event-details-11-b","kind":"text","html":"<p><strong>Intermission</strong><br>Out in the foyer. Grab a coffee, stretch your legs and meet someone new.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"ticket-holder-event-details-12","type":"columns","cols":[[{"id":"ticket-holder-event-details-12-t","kind":"text","html":"<p><strong>4:00pm to 5:30pm</strong></p>"}],[{"id":"ticket-holder-event-details-12-b","kind":"text","html":"<p><strong>Session 2</strong><br>A secret showcase, then the second round of talks.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"ticket-holder-event-details-13","type":"columns","cols":[[{"id":"ticket-holder-event-details-13-t","kind":"text","html":"<p><strong>5:30pm to 6:30pm</strong></p>"}],[{"id":"ticket-holder-event-details-13-b","kind":"text","html":"<p><strong>Drinks hour</strong><br>Join us in the foyer to unpack the afternoon, with a drink and canapes, and keep the conversations going.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"ticket-holder-event-details-14","type":"divider","style":"short","colour":"soft"},{"id":"ticket-holder-event-details-15","type":"header","text":"What to expect","size":"md"},{"id":"ticket-holder-event-details-16","type":"text","html":"<ul><li>Talks and performances from Novocastrians, with every talk under 18 minutes</li><li>Activation spaces to explore, plus the Signal Side Quest, a phone game that runs through the day</li><li>A goody bag to take home</li><li>Artwork by our event artist, Jenni Jean, on display throughout the venue</li><li>The talks are recorded, with the aim of publishing on the TEDx YouTube channel afterwards</li></ul>"},{"id":"ticket-holder-event-details-17","type":"divider","style":"short","colour":"soft"},{"id":"ticket-holder-event-details-18","type":"header","text":"Make a day of it","size":"md"},{"id":"ticket-holder-event-details-19","type":"text","html":"<p>We don't provide a meal, so it's the perfect excuse to head out for lunch before the doors open, and dinner afterwards.</p><p>Local cafes, restaurants, bars and hotels have put together offers for ticket holders across event week. Just show your ticket or email confirmation.</p>"},{"id":"ticket-holder-event-details-20","type":"button","label":"Download the Event Week Guide","href":"https://tedxnewy.com.au/downloads/make-the-most-of-event-week-guide.pdf","align":"center","theme":"red","variant":"solid"},{"id":"ticket-holder-event-details-21","type":"divider","style":"short","colour":"soft"},{"id":"ticket-holder-event-details-22","type":"header","text":"Good to know","size":"md"},{"id":"ticket-holder-event-details-23","type":"text","html":"<ul><li>Smart casual is a great choice. Come comfortable, and feel like you're at something special.</li><li>Angel ticket holders have early access to the event as a thank you. Look out for your arrival details from us.</li><li>Need anything on the day, or have an access requirement? Reply to this email or write to <a href=\"mailto:event@tedxnewy.com.au\">event@tedxnewy.com.au</a>.</li></ul>"},{"id":"ticket-holder-event-details-24","type":"text","html":"<p>See you there.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: ticket holder event details'
);
